style.css:
@-moz-document domain("spotify.com") {
body {
        background-color: #ffd6e8 !important;
        color: #5a5a5a !important;
    }

    .Root__top-container,
    .Root__nav-bar,
    .Root__main-view,
    .Root__main-container {
        background-color: #ffccdd !important;
    }

    .navBar-navBar {
        background-color: #ff99bb !important;
    }

    .navBar-navBar a {
        color: #ffffff !important;
    }

    .main-view-container,
    .main-view-container__scroll-node-child {
        background-color: #ffe6ee !important;
    }

    .progress-bar,
    .volume-bar {
        background-color: #ff99bb !important;
    }

    .button,
    .play-button,
    .control-button {
        background-color: #ff6699 !important;
        color: #fff !important;
        border-radius: 10px !important;
    }

    .button:hover,
    .play-button:hover,
    .control-button:hover {
        background-color: #ff3366 !important;
    }
}
